		public static void EnsureZeroDiskFootprint()
		{
			try
			{
				string appDataDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "MCCheatChecker");
				if (Directory.Exists(appDataDir)) Directory.Delete(appDataDir, true);
			}
			catch { }
			try
			{
				string gdfDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), "gdf");
				if (Directory.Exists(gdfDir)) Directory.Delete(gdfDir, true);
			}
			catch { }
			try
			{
				string authFile = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".mccheatchecker_auth");
				if (File.Exists(authFile)) File.Delete(authFile);
			}
			catch { }
			try
			{
				Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree("Software\\MCCheatChecker", false);
			}
			catch { }
			try
			{
				string temp = Path.GetTempPath();
				string[] tempFiles = new string[] {
					"ram_search_results.txt", "services_event7045.txt", "explorer_typed_paths.txt", "recent_lnk_targets.txt"
				};
				foreach (string tf in tempFiles)
				{
					string fp = Path.Combine(temp, tf);
					if (File.Exists(fp)) File.Delete(fp);
				}
			}
			catch { }
		}

