		public MainForm()
		{
			DoubleBuffered = true;
			InitializeComponent();
			EnsureZeroDiskFootprint();
			base.KeyPreview = true;
			base.KeyDown += MainForm_KeyDown;
			base.Load += MainForm_Load;
			base.Shown += MainForm_Shown;
			EventHandler value = delegate
			{
				ScheduleLayout();
			};
			base.Resize += value;
		}

		private void InitializeComponent()
		{
			this.Text = "MC Cheat Checker — Community Edition";
			base.ClientSize = new System.Drawing.Size(1380, 900);
			this.MinimumSize = new System.Drawing.Size(1100, 700);
			base.StartPosition = System.Windows.Forms.FormStartPosition.CenterScreen;
			this.BackColor = MCCheatChecker.Ui.Backdrop;
			this.ForeColor = MCCheatChecker.Ui.TextPrimary;
			this.Font = MCCheatChecker.Ui.FontBody(9.5f);
			try
			{
				base.Icon = MCCheatChecker.MainForm.BuildAppIcon();
			}
			catch
			{
			}
			this.BuildTopPanel();
			this.BuildControlPanel();
			this.BuildBedrockPanel();
			this.BuildStatusPanel();
			this.BuildBody();
			this.BuildKpiPanel();
			base.Controls.Add(this.splitContainer);
			base.Controls.Add(this.kpiPanel);
			base.Controls.Add(this.bedrockPanel);
			base.Controls.Add(this.controlPanel);
			base.Controls.Add(this.topPanel);
			base.Controls.Add(this.statusPanel);
			this.WireDetectorEvents();
			this.CheckAnyDeskPresence();
			this.DoLayout();
		}

		private void MainForm_Load(object sender, EventArgs e)
		{
			Ui.ApplyDarkTitleBar(this);
			try
			{
				LoadSettings();
			}
			catch
			{
			}
			DoLayout();
		}

		private void MainForm_Shown(object sender, EventArgs e)
		{
			DoLayout();
			splitContainer.Invalidate();
			rightSplit.Invalidate();
			AutoActivateGitHubUtilities();
		}

		private void ScheduleLayout()
		{
			if (!layoutScheduled)
			{
				layoutScheduled = true;
				BeginInvoke((Action)delegate
				{
					layoutScheduled = false;
					DoLayout();
				});
			}
		}

