		private void BuildSidebar(Panel host)
		{
			Panel panel = new Panel();
			panel.Dock = DockStyle.Fill;
			panel.BackColor = Ui.Sidebar;
			categoryListView = new DarkListView();
			categoryListView.Dock = DockStyle.Fill;
			categoryListView.View = View.Details;
			categoryListView.FullRowSelect = true;
			categoryListView.MultiSelect = false;
			categoryListView.HeaderStyle = ColumnHeaderStyle.None;
			categoryListView.BackColor = Ui.Sidebar;
			categoryListView.ForeColor = Ui.TextPrimary;
			categoryListView.BorderStyle = BorderStyle.None;
			categoryListView.Font = Ui.FontBody(9.5f);
			categoryListView.ItemBackColor = Ui.Sidebar;
			categoryListView.RightAlignLastColumn = true;
			categoryListView.HideSelection = true;
			categoryListView.Columns.Add("Категория", 190);
			categoryListView.Columns.Add("Кол-во", 52);
			categoryListView.SelectedIndexChanged += CategoryListView_SelectedIndexChanged;
			Panel panel2 = new Panel();
			panel2.Dock = DockStyle.Bottom;
			panel2.Height = 82;
			panel2.BackColor = Ui.Sidebar;
			quickActionsPanel = new Panel
			{
				Visible = false
			};
			statsPanel = new Panel();
			statsPanel.Location = new Point(12, 10);
			statsPanel.Size = new Size(240, 62);
			statsPanel.BackColor = Ui.Surface;
			panel2.Controls.Add(statsPanel);
			statsPanel.Paint += delegate(object s, PaintEventArgs e)
			{
				e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
				using (GraphicsPath path = Ui.RoundedRect(new Rectangle(0, 0, statsPanel.Width - 1, statsPanel.Height - 1), 7))
				{
					using (Pen pen = new Pen(Ui.Border))
					{
						e.Graphics.DrawPath(pen, path);
					}
				}
			};
			statsVerdictValue = AddStatCell(statsPanel, 0, "ВЕРДИКТ", "—");
			statsDetectedValue = AddStatCell(statsPanel, 1, "НАЙДЕНО", "0");
			statsCriticalValue = AddStatCell(statsPanel, 2, "КРИТИЧ.", "0");
			statsDurationValue = AddStatCell(statsPanel, 3, "СКАН", "—");
			string[] categoryNames = CategoryNames;
			foreach (string text in categoryNames)
			{
				ListViewItem listViewItem = new ListViewItem(text);
				listViewItem.SubItems.Add("0");
				categoryListView.Items.Add(listViewItem);
			}
			if (categoryListView.Items.Count > 0)
			{
				categoryListView.Items[0].Selected = true;
			}
			Panel panel3 = new Panel();
			panel3.Dock = DockStyle.Top;
			panel3.Height = 30;
			panel3.BackColor = Ui.Sidebar;
			panel3.Paint += PanelBottomBorder;
			Label label = new Label();
			label.Text = "КАТЕГОРИИ";
			label.Font = Ui.FontTitle(8f, true);
			label.ForeColor = Ui.TextMuted;
			label.AutoSize = true;
			label.Location = new Point(16, 9);
			panel3.Controls.Add(label);
			panel.Controls.Add(categoryListView);
			panel.Controls.Add(panel2);
			panel.Controls.Add(panel3);
			host.Controls.Add(panel);
		}

		private void AddQuickAction(Panel host, int index, string text, string hint, EventHandler handler)
		{
			int num = index % 2;
			int num2 = index / 2;
			DarkButton darkButton = new DarkButton();
			darkButton.Text = text;
			darkButton.Size = new Size(117, 30);
			darkButton.Location = new Point(num * (darkButton.Width + 6), num2 * 34);
			darkButton.BackColor = Ui.Surface;
			darkButton.ForeColor = Ui.TextSecondary;
			darkButton.Font = Ui.FontBody(8f);
			darkButton.TextAlign = ContentAlignment.MiddleLeft;
			darkButton.Padding = new Padding(8, 0, 4, 0);
			darkButton.Click += handler;
			host.Controls.Add(darkButton);
			tips.SetToolTip(darkButton, hint);
		}

		private Label AddStatCell(Panel host, int index, string caption, string value)
		{
			int num = index % 2;
			int num2 = index / 2;
			int num3 = (host.Width - 20) / 2;
			int num4 = 10 + num * num3;
			int num5 = 6 + num2 * 28;
			Label label = new Label();
			label.Text = caption;
			label.Font = Ui.FontBody(7f, true);
			label.ForeColor = Ui.TextMuted;
			label.AutoSize = false;
			label.Location = new Point(num4, num5);
			label.Size = new Size(num3 - 10, 12);
			host.Controls.Add(label);
			Label label2 = new Label();
			label2.Text = value;
			label2.Font = Ui.FontTitle(9f, true);
			label2.ForeColor = Ui.TextPrimary;
			label2.AutoSize = false;
			label2.AutoEllipsis = true;
			label2.Location = new Point(num4, num5 + 12);
			label2.Size = new Size(num3 - 10, 15);
			host.Controls.Add(label2);
			return label2;
		}

