		private void RefreshProcessList()
		{
			try
			{
				SystemRamInfo systemRamInfo = ProcessMemoryScanner.GetSystemRamInfo();
				if (procsRamStatsLabel != null)
				{
					procsRamStatsLabel.Text = "ОЗУ: " + systemRamInfo.ToString();
				}
				cachedProcesses = ProcessMemoryScanner.GetAllRunningProcesses();
				SortProcessList();
			}
			catch (Exception ex)
			{
				MessageBox.Show("Ошибка чтения процессов: " + ex.Message, "Процессы", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

		private void SortProcessList()
		{
			if (cachedProcesses == null)
			{
				return;
			}
			cachedProcesses.Sort(delegate(ProcessItem a, ProcessItem b)
			{
				int num = 0;
				switch (procsSortCol)
				{
				case 0:
					num = a.Pid.CompareTo(b.Pid);
					break;
				case 1:
					num = string.Compare(a.Name, b.Name, StringComparison.OrdinalIgnoreCase);
					break;
				case 2:
					num = string.Compare(a.WindowTitle, b.WindowTitle, StringComparison.OrdinalIgnoreCase);
					break;
				case 3:
					num = a.MemoryBytes.CompareTo(b.MemoryBytes);
					break;
				case 4:
					num = string.Compare(a.ThreatReason, b.ThreatReason, StringComparison.OrdinalIgnoreCase);
					break;
				case 5:
					num = string.Compare(a.ExecutablePath, b.ExecutablePath, StringComparison.OrdinalIgnoreCase);
					break;
				default:
					num = a.Pid.CompareTo(b.Pid);
					break;
				}
				return (!procsSortAsc) ? (-num) : num;
			});
			FilterProcessList((searchProcsBox != null) ? searchProcsBox.Text : "");
		}

		private void FilterProcessList(string query)
		{
			if (procsListView == null || cachedProcesses == null)
			{
				return;
			}
			string value = (query ?? "").Trim().ToLowerInvariant();
			procsListView.BeginUpdate();
			procsListView.Items.Clear();
			foreach (ProcessItem cachedProcess in cachedProcesses)
			{
				if (string.IsNullOrEmpty(value) || cachedProcess.Pid.ToString().Contains(value) || (cachedProcess.Name != null && cachedProcess.Name.ToLowerInvariant().Contains(value)) || (cachedProcess.WindowTitle != null && cachedProcess.WindowTitle.ToLowerInvariant().Contains(value)) || (cachedProcess.ExecutablePath != null && cachedProcess.ExecutablePath.ToLowerInvariant().Contains(value)) || (cachedProcess.ThreatReason != null && cachedProcess.ThreatReason.ToLowerInvariant().Contains(value)))
				{
					ListViewItem listViewItem = new ListViewItem(cachedProcess.Pid.ToString());
					listViewItem.SubItems.Add(cachedProcess.Name);
					listViewItem.SubItems.Add(string.IsNullOrEmpty(cachedProcess.WindowTitle) ? "—" : cachedProcess.WindowTitle);
					listViewItem.SubItems.Add(cachedProcess.MemoryString);
					listViewItem.SubItems.Add(cachedProcess.ThreatReason ?? "Норма");
					listViewItem.SubItems.Add(cachedProcess.ExecutablePath ?? "");
					if (cachedProcess.IsThreat)
					{
						listViewItem.ForeColor = Ui.AccentRed;
					}
					else if (cachedProcess.IsMinecraft)
					{
						listViewItem.ForeColor = Ui.AccentTeal;
					}
					else
					{
						listViewItem.ForeColor = Ui.TextPrimary;
					}
					procsListView.Items.Add(listViewItem);
				}
			}
			procsListView.EndUpdate();
		}

		private void RunJavawRamScan()
		{
			try
			{
				List<MemoryRegionHit> list = ProcessMemoryScanner.ScanMinecraftRam(0);
				if (list.Count == 0)
				{
					MessageBox.Show("javaw.exe не запущен или чит-модификаций в памяти не обнаружено.", "Анализ RAM", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				StringBuilder stringBuilder = new StringBuilder();
				int num = 0;
				foreach (MemoryRegionHit item in list)
				{
					stringBuilder.AppendLine(string.Format("[{0}] Адрес: {1} | Размер: {2} | Тип: {3} | Детали: {4}", item.Severity, item.Address, item.Size, item.Type, item.Detail));
					if (item.Severity == CheckSeverity.Critical || item.Severity == CheckSeverity.NeedsCheck)
					{
						num++;
					}
				}
				MessageBox.Show(stringBuilder.ToString(), string.Format("Результаты сканирования памяти ({0} находок)", num), MessageBoxButtons.OK, (num > 0) ? MessageBoxIcon.Exclamation : MessageBoxIcon.Asterisk);
			}
			catch (Exception ex)
			{
				MessageBox.Show("Ошибка сканирования памяти: " + ex.Message, "RAM", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

