		private async void RunModsScan()
		{
			if (modsStatsLabel != null)
			{
				modsStatsLabel.Text = "Сканирование папок .minecraft, Prism, Lunar, CurseForge...";
			}
			if (modsListView != null)
			{
				modsListView.Items.Clear();
				modDetailsBox.Clear();
			}
			try
			{
				List<InternalStringHit> hits = await Task.Run(() => ModStringInspector.ScanAllKnownModAndDangerLocations());
				if (modsListView == null)
				{
					return;
				}
				cachedModHits = hits;
				SortModsList();
				int threatCount = 0;
				foreach (InternalStringHit item in hits)
				{
					if (item.IsThreat)
					{
						threatCount++;
					}
				}
				if (modsStatsLabel != null)
				{
					modsStatsLabel.Text = string.Format("Проверено файлов: {0} | Найдено угроз: {1}", hits.Count, threatCount);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Ошибка сканирования модов: " + ex.Message, "Моды", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

		private void SortModsList()
		{
			if (cachedModHits == null)
			{
				return;
			}
			cachedModHits.Sort(delegate(InternalStringHit a, InternalStringHit b)
			{
				int num = 0;
				switch (modsSortCol)
				{
				case 0:
					num = string.Compare(a.FileName, b.FileName, StringComparison.OrdinalIgnoreCase);
					break;
				case 1:
					num = string.Compare(a.FileType, b.FileType, StringComparison.OrdinalIgnoreCase);
					break;
				case 2:
					num = a.FileSizeBytes.CompareTo(b.FileSizeBytes);
					break;
				case 3:
					num = a.MatchedSignatures.Count.CompareTo(b.MatchedSignatures.Count);
					break;
				case 4:
					num = string.Compare(a.ThreatTitle, b.ThreatTitle, StringComparison.OrdinalIgnoreCase);
					break;
				case 5:
					num = string.Compare(a.FilePath, b.FilePath, StringComparison.OrdinalIgnoreCase);
					break;
				default:
					num = string.Compare(a.FileName, b.FileName, StringComparison.OrdinalIgnoreCase);
					break;
				}
				return (!modsSortAsc) ? (-num) : num;
			});
			FilterModsList((searchModsBox != null) ? searchModsBox.Text : "");
		}

		private void FilterModsList(string query)
		{
			if (modsListView == null || cachedModHits == null)
			{
				return;
			}
			string q = (query ?? "").Trim().ToLowerInvariant();
			bool flag = chkOnlyThreatMods != null && chkOnlyThreatMods.Checked;
			modsListView.BeginUpdate();
			modsListView.Items.Clear();
			foreach (InternalStringHit cachedModHit in cachedModHits)
			{
				if ((!flag || cachedModHit.IsThreat) && (string.IsNullOrEmpty(q) || (cachedModHit.FileName != null && cachedModHit.FileName.ToLowerInvariant().Contains(q)) || (cachedModHit.FilePath != null && cachedModHit.FilePath.ToLowerInvariant().Contains(q)) || (cachedModHit.ThreatTitle != null && cachedModHit.ThreatTitle.ToLowerInvariant().Contains(q)) || cachedModHit.MatchedSignatures.Any((string s) => s.ToLowerInvariant().Contains(q))))
				{
					ListViewItem listViewItem = new ListViewItem(cachedModHit.FileName);
					listViewItem.SubItems.Add(cachedModHit.FileType);
					listViewItem.SubItems.Add(cachedModHit.FileSizeString);
					listViewItem.SubItems.Add(cachedModHit.MatchedSignatures.Count.ToString());
					listViewItem.SubItems.Add(cachedModHit.ThreatTitle);
					listViewItem.SubItems.Add(cachedModHit.FilePath);
					listViewItem.Tag = cachedModHit;
					if (cachedModHit.IsThreat)
					{
						listViewItem.ForeColor = Ui.AccentRed;
					}
					else
					{
						listViewItem.ForeColor = Ui.TextPrimary;
					}
					modsListView.Items.Add(listViewItem);
				}
			}
			modsListView.EndUpdate();
		}

