			List<double> clickDelays = new List<double>();
			long lastClickTick = 0L;
			double peakCps = 0.0;
			int totalClicks = 0;
			Action updateCpsMetrics = delegate
			{
				long timestamp = Stopwatch.GetTimestamp();
				long oneSecAgo = timestamp - Stopwatch.Frequency;
				clickTimestamps.RemoveAll((long t) => t < oneSecAgo);
				double num10 = clickTimestamps.Count;
				if (num10 > peakCps)
				{
					peakCps = num10;
				}
				lblCpsVal.Text = num10.ToString("0.0");
				lblPeakVal.Text = peakCps.ToString("0.0");
				lblTotalVal.Text = totalClicks.ToString();
				if (clickDelays.Count > 0)
				{
					double num11 = clickDelays.Min();
					double avg = clickDelays.Average();
					double num12 = clickDelays.Sum((double d) => Math.Pow(d - avg, 2.0));
					double num13 = Math.Sqrt(num12 / (double)clickDelays.Count);
					lblMinVal.Text = num11.ToString("0") + " ms";
					lblAvgVal.Text = avg.ToString("0") + " ms";
					lblStdVal.Text = num13.ToString("0.0") + " ms";
					if (totalClicks >= 10)
					{
						if (num11 < 15.0)
						{
							lblVerdictText.Text = string.Format("⚠\ufe0f ОБНАРУЖЕН ДВОЙНОЙ КЛИК!\nЗадержка всего {0:0} мс (<15 мс).\nВозможен 0ms Debounce Time / баттерфляй макрос.", num11);
							lblVerdictText.ForeColor = Ui.AccentOrange;
						}
						else if (num13 < 4.0 && totalClicks >= 15)
						{
							lblVerdictText.Text = string.Format("\ud83d\udea8 ОБНАРУЖЕН АВТОКЛИКЕР / МАКРОС!\nПодозрительно постоянный интервал!\nДжиттер всего {0:0.0} мс (искусственный клик).", num13);
							lblVerdictText.ForeColor = Ui.AccentRed;
						}
						else
						{
							lblVerdictText.Text = string.Format("\ud83d\udfe2 КЛИК ЧЕЛОВЕЧЕСКИЙ (НОРМА)\nДжиттер {0:0.0} мс, мин. задержка {1:0} мс.\nЕстественная человеческая дисперсия.", num13, num11);
							lblVerdictText.ForeColor = Ui.AccentGreen;
						}
					}
				}
			};
			MouseEventHandler value7 = delegate
			{
				long timestamp = Stopwatch.GetTimestamp();
				totalClicks++;
				clickTimestamps.Add(timestamp);
				if (lastClickTick > 0)
				{
					double num10 = (double)(timestamp - lastClickTick) / (double)Stopwatch.Frequency * 1000.0;
					if (num10 > 0.0 && num10 < 1500.0)
					{
						clickDelays.Add(num10);
						if (clickDelays.Count > 60)
						{
							clickDelays.RemoveAt(0);
						}
					}
				}
				lastClickTick = timestamp;
				updateCpsMetrics();
			};
			button.MouseDown += value7;
			darkButton10.Click += delegate
			{
				clickTimestamps.Clear();
				clickDelays.Clear();
				lastClickTick = 0L;
				peakCps = 0.0;
				totalClicks = 0;
