				lblVerdictText.ForeColor = Ui.TextSecondary;
				SetStatus("Тестер кликов и CPS сброшен.", Ui.AccentTeal);
			};
			return panel;
		}

		private void OpenSelectedSocketWhois()
		{
			if (networkListView == null || networkListView.SelectedItems.Count == 0)
			{
				return;
			}
			try
			{
				string text = networkListView.SelectedItems[0].SubItems[3].Text;
				string text2 = text.Split(':')[0].Trim();
				if (!string.IsNullOrEmpty(text2) && text2 != "0.0.0.0" && text2 != "127.0.0.1" && text2 != "*" && !text2.StartsWith("["))
				{
					Process.Start("https://ipinfo.io/" + text2);
				}
			}
			catch
			{
			}
		}

		private void ToggleNetworkMode()
		{
			showingDnsCache = !showingDnsCache;
			if (showingDnsCache)
			{
				btnToggleNetworkMode.Text = "\ud83c\udf10  Показать Сокеты";
				btnToggleNetworkMode.ForeColor = Ui.AccentBlue;
				chkOnlySuspiciousSockets.Text = "⚠\ufe0f Только подозрительные домены читов";
				searchNetworkBox.Placeholder = "Поиск по домену / IP / статусу...";
				networkListView.Columns.Clear();
				networkListView.Columns.Add("Тип", 80);
				networkListView.Columns.Add("TTL", 100);
				networkListView.Columns.Add("Доменное имя / Хост", 260);
				networkListView.Columns.Add("Разрешённый IP / Данные", 220);
