			btnDeepToolScan.Font = Ui.FontBody(8.5f, true);
			btnDeepToolScan.Cursor = Cursors.Hand;
			btnDeepToolScan.Click += delegate
			{
				try
				{
					SetStatus("Выполняется сканирование по базам Doomsday, Clean Detecting, SSTool, y_check...", Ui.AccentTeal);
					List<CheckResult> results = SsToolsManager.RunAllIntegratedToolScans();
					if (lastReport != null)
					{
						foreach (CheckResult cr in results)
						{
							if (!lastReport.Results.Any(r => r.Name == cr.Name))
							{
								lastReport.Results.Add(cr);
							}
						}
						DisplayReport(lastReport);
					}
					SetStatus("✅ Анализ завершён: обнаружено улик — " + results.Count(r => r.Detected), Ui.AccentGreen);
					bottomTabs.SelectedIndex = 0;
				}
				catch (Exception ex)
				{
					SetStatus("Ошибка сканирования: " + ex.Message, Ui.AccentRed);
				}
			};
			pnlHeader.Controls.Add(btnDeepToolScan);

			

			DarkButton btnLaunchAll = new DarkButton();
			btnLaunchAll.Text = "🚀  Запустить все найденные";
			btnLaunchAll.Size = new Size(210, 28);
			btnLaunchAll.Location = new Point(966, 76);
			btnLaunchAll.BackColor = Ui.SurfaceAlt;
			btnLaunchAll.ForeColor = Ui.AccentGreen;
			btnLaunchAll.Font = Ui.FontBody(8.5f, true);
			btnLaunchAll.Click += delegate
			{
				int launched = 0;
				foreach (SsToolsManager.SsToolDefinition t in SsToolsManager.GetTools())
				{
					if (t.IsInstalled())
					{
						t.Launch(delegate(string msg) { SetStatus(msg, Ui.AccentTeal); });
						launched++;
					}
				}
				if (launched > 0)
				{
					SetStatus("Запущено утилит: " + launched, Ui.AccentGreen);
				}
				else
				{
					MessageBox.Show(
						"Локально не найдено .exe внешних утилит.\nПоместите нужные файлы в папку 'tools' рядом с программой.",
						"Внешние утилиты",
						MessageBoxButtons.OK,
						MessageBoxIcon.Information);
				}
			};
			pnlHeader.Controls.Add(btnLaunchAll);

			root.Controls.Add(pnlHeader);

			Panel pnlGrid = new Panel();
			pnlGrid.Dock = DockStyle.Fill;
			pnlGrid.BackColor = Ui.Backdrop;
			pnlGrid.AutoScroll = true;
			pnlGrid.Padding = new Padding(20, 16, 20, 20);

			Panel pnlPillCard = new Panel();
			pnlPillCard.Location = new Point(20, 16);
			pnlPillCard.Size = new Size(1060, 390);
			pnlPillCard.BackColor = Color.FromArgb(19, 20, 28);
			pnlPillCard.Paint += delegate(object s, PaintEventArgs e)
			{
				using (Pen pen = new Pen(Color.FromArgb(45, 48, 64)))
				{
					using (GraphicsPath path = Ui.RoundedRect(new Rectangle(0, 0, pnlPillCard.Width - 1, pnlPillCard.Height - 1), 10))
					{
						e.Graphics.DrawPath(pen, path);
					}
				}
			};

			Label lblPills = new Label();
			lblPills.Text = "ИНСТРУМЕНТЫ SCREENSHARE (SS TOOLS):";
			lblPills.Font = Ui.FontTitle(8.5f, true);
			lblPills.ForeColor = Color.FromArgb(140, 145, 170);
			lblPills.Location = new Point(20, 14);
			lblPills.AutoSize = true;
			pnlPillCard.Controls.Add(lblPills);

			List<SsToolsManager.SsToolDefinition> allTools = SsToolsManager.GetTools();
			Dictionary<string, SsToolsManager.SsToolDefinition> toolMap = allTools.ToDictionary(t => t.Id);

			string[][] pillRows = new string[][]
			{
				new string[] { "javaw", "sstool", "system_informer", "shellbag_analyzer" },
				new string[] { "journal_trace" },
				new string[] { "defender_log", "userassist_view", "recent_files_view" },
				new string[] { "browsing_history_view", "browser_downloads_view" },
				new string[] { "shell_bags_view", "executed_programs_list", "clean_detecting" },
				new string[] { "everything", "meow_doomsday_fucker", "y_check" }
			};

			int curY = 40;
			foreach (string[] row in pillRows)
			{
				int curX = 20;
				foreach (string toolId in row)
				{
					if (!toolMap.ContainsKey(toolId)) continue;
					SsToolsManager.SsToolDefinition def = toolMap[toolId];

					DarkButton pillBtn = new DarkButton();
					bool installed = def.IsInstalled();
					pillBtn.Text = def.Title + "  ↗";
					pillBtn.Font = Ui.FontBody(9f, true);
					pillBtn.Height = 34;
					pillBtn.Cursor = Cursors.Hand;
					pillBtn.BackColor = Color.FromArgb(37, 39, 52);
					pillBtn.ForeColor = installed ? Ui.AccentGreen : Color.FromArgb(235, 235, 245);

					using (Graphics g = pillBtn.CreateGraphics())
					{
						int textW = (int)g.MeasureString(pillBtn.Text, pillBtn.Font).Width;
						pillBtn.Width = Math.Max(120, textW + 34);
					}

					pillBtn.Location = new Point(curX, curY);

					ToolTip tt = new ToolTip();
					string statusDesc = installed ? ("Установлена локально: " + def.FindExecutable()) : ("Не найдена (нажмите для перехода на GitHub/сайт)");
					tt.SetToolTip(pillBtn, def.Title + "\n" + def.Description + "\n\n" + statusDesc);

					pillBtn.Click += delegate
					{
						def.Launch(delegate(string msg) { SetStatus(msg, Ui.AccentTeal); });
					};

					pnlPillCard.Controls.Add(pillBtn);
					curX += pillBtn.Width + 12;
				}
				curY += 46;
			}

			pnlPillCard.Height = Math.Max(350, curY + 16);

			pnlGrid.Controls.Add(pnlPillCard);
			root.Controls.Add(pnlGrid);
			pnlHeader.BringToFront();

			return root;
		}

		private void ShowRemoteAccessTraces()
		{
			if (networkListView == null) return;
			try
			{
				showingDnsCache = false;
				btnToggleNetworkMode.Text = "📡  Показать Кэш DNS";
				btnToggleNetworkMode.ForeColor = Ui.AccentTeal;
				chkOnlySuspiciousSockets.Text = "🚨 Только подозрительные (Передача файлов / Remote Shell)";
				searchNetworkBox.Placeholder = "Поиск по ID / событию / файлу...";

				networkListView.BeginUpdate();
				networkListView.Columns.Clear();
				networkListView.Columns.Add("Время", 140);
				networkListView.Columns.Add("Программа / Категория", 180);
				networkListView.Columns.Add("ID партнёра", 130);
				networkListView.Columns.Add("Описание события / Передача файлов", 460);
				networkListView.Columns.Add("Статус", 140);

				List<AnyDeskTraceItem> traces = NetworkAndRemoteForensics.GetAnyDeskTraceEvents();
				networkListView.Items.Clear();
				string filter = (searchNetworkBox != null) ? searchNetworkBox.Text.Trim().ToLowerInvariant() : "";
				bool onlySusp = (chkOnlySuspiciousSockets != null && chkOnlySuspiciousSockets.Checked);
				int warnCount = 0;

				foreach (AnyDeskTraceItem t in traces)
				{
					if (t.IsWarning) warnCount++;
					if (onlySusp && !t.IsWarning) continue;
					if (!string.IsNullOrEmpty(filter))
					{
						if (!(t.Time ?? "").ToLowerInvariant().Contains(filter) &&
							!(t.Category ?? "").ToLowerInvariant().Contains(filter) &&
							!(t.RemoteId ?? "").ToLowerInvariant().Contains(filter) &&
							!(t.Description ?? "").ToLowerInvariant().Contains(filter))
						{
							continue;
						}
					}

					ListViewItem lvi = new ListViewItem(string.IsNullOrEmpty(t.Time) ? "—" : t.Time);
					lvi.SubItems.Add(t.Category ?? "");
					lvi.SubItems.Add(t.RemoteId ?? "—");
					lvi.SubItems.Add(t.Description ?? "");
					lvi.SubItems.Add(t.IsWarning ? "🚨 ВНИМАНИЕ" : "✅ Обычное");

					if (t.IsWarning)
					{
						lvi.ForeColor = Ui.AccentRed;
						lvi.BackColor = Color.FromArgb(45, 20, 24);
					}
					else
					{
						lvi.ForeColor = Ui.TextPrimary;
					}
					networkListView.Items.Add(lvi);
				}
				networkListView.EndUpdate();

				if (lblSocketsStats != null)
				{
					lblSocketsStats.Text = string.Format("Событий сессий: {0} (Подозрительных: {1})", traces.Count, warnCount);
					lblSocketsStats.ForeColor = (warnCount > 0) ? Ui.AccentRed : Ui.AccentPurple;
				}
			}
			catch
			{
			}
		}

		private void RefreshDnsCacheList()
		{
			try
			{
				cachedDnsEntries = NetworkAndRemoteForensics.GetDnsCacheEntries();
				ApplyDnsCacheFilter();
			}
			catch
			{
			}
		}

		private void ApplyDnsCacheFilter()
		{
			if (networkListView == null)
			{
				return;
			}
			networkListView.BeginUpdate();
			networkListView.Items.Clear();
			string value = ((searchNetworkBox != null) ? searchNetworkBox.Text.Trim().ToLowerInvariant() : "");
			bool flag = chkOnlySuspiciousSockets != null && chkOnlySuspiciousSockets.Checked;
			int num = 0;
			int num2 = 0;
			foreach (DnsCacheEntry cachedDnsEntry in cachedDnsEntries)
			{
				if (cachedDnsEntry.IsSuspicious)
				{
					num++;
				}
				if ((!flag || cachedDnsEntry.IsSuspicious) && (string.IsNullOrEmpty(value) || (cachedDnsEntry.Domain ?? "").ToLowerInvariant().Contains(value) || (cachedDnsEntry.Data ?? "").ToLowerInvariant().Contains(value) || (cachedDnsEntry.Category ?? "").ToLowerInvariant().Contains(value)))
				{
					num2++;
					ListViewItem listViewItem = new ListViewItem(cachedDnsEntry.RecordType);
					listViewItem.SubItems.Add(cachedDnsEntry.Ttl);
					listViewItem.SubItems.Add(cachedDnsEntry.Domain);
					listViewItem.SubItems.Add(cachedDnsEntry.Data);
					listViewItem.SubItems.Add(cachedDnsEntry.Category);
					listViewItem.SubItems.Add(cachedDnsEntry.IsSuspicious ? "\ud83d\udea8 ПОДОЗРИТЕЛЬНО" : "\ud83d\udfe2 Легитимный");
					if (cachedDnsEntry.IsSuspicious)
					{
						listViewItem.ForeColor = Ui.AccentRed;
						listViewItem.BackColor = Color.FromArgb(45, 20, 24);
					}
					else
					{
						listViewItem.ForeColor = Ui.TextPrimary;
					}
					networkListView.Items.Add(listViewItem);
				}
			}
			networkListView.EndUpdate();
			if (lblSocketsStats != null)
			{
				lblSocketsStats.Text = string.Format("Записей DNS: {0} (Подозрительных: {1})", num2, num);
				lblSocketsStats.ForeColor = ((num > 0) ? Ui.AccentRed : Ui.AccentTeal);
			}
		}

		private void RefreshNetworkSocketsList()
		{
			if (showingDnsCache)
			{
				RefreshDnsCacheList();
				return;
			}
			try
			{
				cachedNetworkSockets = NetworkAndRemoteForensics.GetActiveMinecraftSockets();
				ApplyNetworkSocketsFilter();
			}
			catch
			{
			}
		}

		private void ApplyNetworkSocketsFilter()
		{
			if (showingDnsCache)
			{
				ApplyDnsCacheFilter();
			}
			else
			{
				if (networkListView == null)
				{
					return;
				}
				try
				{
					string value = ((searchNetworkBox != null) ? searchNetworkBox.Text.Trim().ToLowerInvariant() : "");
					bool flag = chkOnlySuspiciousSockets != null && chkOnlySuspiciousSockets.Checked;
					networkListView.BeginUpdate();
					networkListView.Items.Clear();
					int num = 0;
					foreach (NetworkSocketItem cachedNetworkSocket in cachedNetworkSockets)
					{
						if ((!flag || cachedNetworkSocket.IsSuspicious) && (string.IsNullOrEmpty(value) || (cachedNetworkSocket.ProcessName ?? "").ToLowerInvariant().Contains(value) || (cachedNetworkSocket.LocalEndpoint ?? "").ToLowerInvariant().Contains(value) || (cachedNetworkSocket.RemoteEndpoint ?? "").ToLowerInvariant().Contains(value) || (cachedNetworkSocket.State ?? "").ToLowerInvariant().Contains(value) || (cachedNetworkSocket.Verdict ?? "").ToLowerInvariant().Contains(value)))
						{
							ListViewItem listViewItem = new ListViewItem(cachedNetworkSocket.Pid.ToString());
							listViewItem.SubItems.Add(cachedNetworkSocket.ProcessName);
							listViewItem.SubItems.Add(cachedNetworkSocket.LocalEndpoint);
							listViewItem.SubItems.Add(cachedNetworkSocket.RemoteEndpoint);
							listViewItem.SubItems.Add(cachedNetworkSocket.State);
							listViewItem.SubItems.Add(cachedNetworkSocket.Verdict);
							if (cachedNetworkSocket.IsSuspicious)
							{
								listViewItem.ForeColor = Ui.AccentRed;
							}
							else
							{
								listViewItem.ForeColor = Ui.TextPrimary;
							}
							networkListView.Items.Add(listViewItem);
							num++;
						}
					}
					networkListView.EndUpdate();
					if (lblSocketsStats != null)
					{
						lblSocketsStats.Text = string.Format("Соединений: {0} из {1}", num, cachedNetworkSockets.Count);
					}
				}
				catch
				{
				}
			}
		}

		private void RefreshNetworkAndAnyDesk()
		{
			RefreshNetworkSocketsList();
		}

		private static TextBox MakeHelpBox(string text)
		{
			TextBox box = new TextBox();
			box.Dock = DockStyle.Fill;
			box.Multiline = true;
			box.ScrollBars = ScrollBars.Vertical;
			box.ReadOnly = true;
			box.BorderStyle = BorderStyle.None;
			box.BackColor = Ui.Backdrop;
			box.ForeColor = Ui.TextPrimary;
			box.Font = Ui.FontBody(9.5f);
			box.Text = text;
			box.HandleCreated += delegate
			{
				Ui.ApplyDarkScrollbars(box);
			};
			return box;
		}

