		private void UpdateKpi(ScanReport report)
		{
			if (report != null)
			{
				int count = report.Results.Count;
				int criticalCount = report.CriticalCount;
				int visualsCount = report.VisualsCount;
				int warningCount = report.WarningCount;
				int infoCount = report.InfoCount;
				int num = count - report.TotalDetected;
				cardCritical.SetValue(criticalCount);
				cardNeeds.SetValue(visualsCount);
				cardWarn.SetValue(warningCount);
				cardInfo.SetValue(infoCount);
				severityBar.SetCounts(criticalCount, visualsCount, warningCount, infoCount);
				int score = 100;
				if (criticalCount > 0)
				{
					score = Math.Max(0, 40 - criticalCount * 8);
				}
				else if (visualsCount > 0)
				{
					score = Math.Max(35, 70 - visualsCount * 5);
				}
				else if (warningCount > 0)
				{
					score = Math.Max(55, 88 - warningCount * 3);
				}
				scoreRing.Score = score;
				Color color = ((criticalCount > 0) ? Ui.AccentRed : ((visualsCount > 0) ? Ui.AccentPurple : ((warningCount > 0) ? Ui.AccentOrange : Ui.AccentTeal)));
				scoreRing.Accent = color;
				kpiVerdictLabel.Text = report.Verdict;
				kpiVerdictLabel.ForeColor = color;
				kpiSubLabel.Text = "Проверок: " + count + "  ·  обнаружено: " + report.TotalDetected + "  ·  чисто: " + num + "  ·  игрок: " + (string.IsNullOrEmpty(report.PlayerName) ? "—" : report.PlayerName) + "  ·  " + report.ScanTime.ToString("HH:mm:ss dd.MM.yyyy");
				if (statsVerdictValue != null)
				{
					statsVerdictValue.Text = ((criticalCount > 0) ? "УГРОЗА" : ((visualsCount > 0) ? "ВИЗУАЛ" : ((warningCount > 0) ? "СЛЕДЫ" : "ЧИСТО")));
					statsVerdictValue.ForeColor = color;
					statsDetectedValue.Text = report.TotalDetected.ToString();
					statsCriticalValue.Text = criticalCount.ToString();
					statsCriticalValue.ForeColor = ((criticalCount > 0) ? Ui.AccentRed : Ui.TextPrimary);
				}
			}
		}

