				int num12 = Math.Max(118, Math.Min(172, (num11 - num10 * 3) / 4));
				int num13 = num12 * 4 + num10 * 3;
				for (int i = 0; i < kpiCards.Controls.Count; i++)
				{
					Control control = kpiCards.Controls[i];
					control.Size = new Size(num12, 90);
					control.Location = new Point(i * (num12 + num10), 0);
				}
				kpiCards.Size = new Size(num13, 94);
				kpiCards.Location = new Point(Math.Max(128, num9 - 16 - num13), 10);
				int num14 = Math.Max(160, kpiCards.Left - 128 - 24);
				kpiSubLabel.Width = num14;
				severityBar.Width = num14;
				kpiVerdictLabel.MaximumSize = new Size(num14, 0);
			}
			if (categoryListView != null)
			{
				int num15 = Math.Max(120, 194);
				if (categoryListView.Columns.Count > 0)
				{
					categoryListView.Columns[0].Width = num15;
				}
			}
			if (resultsListView != null && resultsListView.Columns.Count == 5)
			{
				int num16 = Math.Max(700, resultsListView.ClientSize.Width - 4);
				int num17 = 568;
				int num18 = Math.Max(300, num16 - num17);
				resultsListView.Columns[3].Width = (int)((double)num18 * 0.48);
				resultsListView.Columns[4].Width = Math.Max(220, num18 - resultsListView.Columns[3].Width);
			}
			ApplySplit();
		}

		private void ApplySplit()
		{
			int num = splitContainer.ClientSize.Width;
			if (num > 420)
			{
				int val = 264;
				int panel1MinSize = splitContainer.Panel1MinSize;
				int val2 = num - splitContainer.Panel2MinSize - splitContainer.SplitterWidth;
				val = Math.Max(panel1MinSize, Math.Min(val, val2));
				if (splitContainer.Orientation == Orientation.Vertical && Math.Abs(splitContainer.SplitterDistance - val) > 1)
				{
					splitContainer.SplitterDistance = val;
				}
			}
			int num2 = rightSplit.ClientSize.Height;
			if (num2 > 260)
			{
				int val3 = Math.Max(180, num2 - 264);
				int panel1MinSize2 = rightSplit.Panel1MinSize;
				int val4 = num2 - rightSplit.Panel2MinSize - rightSplit.SplitterWidth;
				val3 = Math.Max(panel1MinSize2, Math.Min(val3, val4));
				if (Math.Abs(rightSplit.SplitterDistance - val3) > 1)
				{
					rightSplit.SplitterDistance = val3;
				}
			}
		}

