		public void AutoActivateGitHubUtilities()
		{
			try
			{
				SsToolsManager.ActivateAllGitHubTools(delegate(string msg)
				{
					SetStatus(msg, Ui.AccentTeal);
					try
					{
						if (logBox != null && !logBox.IsDisposed)
						{
							logBox.AppendText("[" + DateTime.Now.ToString("HH:mm:ss") + "] " + msg + "\r\n");
						}
					}
					catch { }
				});
			}
			catch { }
		}

		private void WireDetectorEvents()
		{
			CheatDetector.OnProgress += delegate(string msg)
			{
				if (base.IsDisposed)
				{
					return;
				}
				try
				{
					BeginInvoke((Action)delegate
					{
						logBox.AppendText("[" + DateTime.Now.ToString("HH:mm:ss") + "] " + msg + "\r\n");
						statusText.Text = msg;
					});
				}
				catch
				{
				}
			};
			CheatDetector.OnProgressStep += delegate(int current, int total, string msg)
			{
				if (base.IsDisposed)
				{
					return;
				}
				try
				{
					BeginInvoke((Action)delegate
					{
						int num = ((total > 0) ? Math.Min(100, (int)((double)current / (double)total * 100.0)) : 0);
						scanProgressBar.Value = num;
						stepProgressLabel.Text = string.Format("[{0}/{1} {2}%]", current, total, num);
					});
				}
				catch
				{
				}
			};
		}

		private async void StartButton_Click(object sender, EventArgs e)
		{
			if (isScanning)
			{
				return;
			}
			AutoActivateGitHubUtilities();
			string pName = (string.IsNullOrEmpty(playerNameBox.Text.Trim()) ? SafeUserName() : playerNameBox.Text.Trim());
			isScanning = true;
			startButton.Enabled = false;
			stopButton.Enabled = true;
			scanProgressBar.Value = 0;
			stepProgressLabel.Text = "[0/0 0%]";
			SaveSettings();
				EnsureZeroDiskFootprint();
			isSsPaused = false;
			logBox.Clear();
			evidenceBox.Clear();
			resultsListView.Items.Clear();
			pathHeaderLabel.Text = "Путь: выберите строку в таблице выше";
			openFolderBtn.Enabled = false;
			copyPathBtn.Enabled = false;
			currentDetectedPath = "";
			verdictLabel.Text = "СТАТУС: ИДЁТ ПОЛНОЕ СКАНИРОВАНИЕ...";
			verdictLabel.ForeColor = Ui.AccentOrange;
			SetStatus("Сканирование: " + pName, Ui.AccentTeal);
			CheckAnyDeskPresence();
			cts = new CancellationTokenSource();
			Stopwatch watch = Stopwatch.StartNew();
			try
			{
				int num = default(int);
				int num2 = num;
				
				try
				{
					ScanReport report = await Task.Run(() => CheatDetector.RunFullScan(pName, cts.Token));
					watch.Stop();
					lastReport = report;
					DisplayReport(report);
					if (statsDurationValue != null)
					{
						statsDurationValue.Text = ((watch.Elapsed.TotalSeconds >= 60.0) ? string.Format("{0:0.0} мин", watch.Elapsed.TotalSeconds / 60.0) : string.Format("{0:0} с", watch.Elapsed.TotalSeconds));
					}
					SetStatus("Проверка завершена за " + watch.Elapsed.ToString("mm\\:ss") + " · найдено: " + report.TotalDetected, Ui.AccentTeal);
				}
				catch (OperationCanceledException)
				{
					verdictLabel.Text = "СТАТУС: ПРОВЕРКА ОСТАНОВЛЕНА";
					verdictLabel.ForeColor = Ui.AccentOrange;
					SetStatus("Проверка остановлена", Ui.AccentOrange);
				}
				catch (Exception ex2)
				{
					MessageBox.Show("Ошибка сканирования: " + ex2.Message, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Hand);
					SetStatus("Ошибка: " + ex2.Message, Ui.AccentRed);
				}
			}
			finally
			{
				isScanning = false;
				startButton.Enabled = true;
				stopButton.Enabled = false;
				scanProgressBar.Value = 100;
				stepProgressLabel.Text = "[ГОТОВО]";
				try
				{
					SystemSounds.Asterisk.Play();
				}
				catch
				{
				}
			}
		}

		private void StopButton_Click(object sender, EventArgs e)
		{
			if (cts != null)
			{
				cts.Cancel();
			}
			ssTimer.Stop();
			verdictLabel.Text = "СТАТУС: ПРОВЕРКА ОСТАНОВЛЕНА ПОЛЬЗОВАТЕЛЕМ";
			verdictLabel.ForeColor = Ui.AccentOrange;
			startButton.Enabled = true;
			stopButton.Enabled = false;
			isScanning = false;
		}

		private void SetStatus(string text, Color color)
		{
			statusText.Text = text;
			statusText.ForeColor = color;
		}

		private void DisplayReport(ScanReport report)
		{
			verdictLabel.Text = "ВЕРДИКТ: " + report.Verdict;
			verdictLabel.ForeColor = ((report.CriticalCount > 0) ? Ui.AccentRed : ((report.VisualsCount > 0) ? Ui.AccentPurple : ((report.WarningCount > 0) ? Ui.AccentOrange : Ui.AccentGreen)));
			RebuildCategoryList();
			RefreshResultsView();
			UpdateKpi(report);
			try
			{
				RefreshProcessList();
				RunModsScan();
				RefreshNetworkAndAnyDesk();
			}
			catch
			{
			}
		}

		private void RebuildCategoryList()
		{
			if (lastReport == null)
			{
				return;
			}
			string value = currentCategory;
			categoryListView.BeginUpdate();
			categoryListView.Items.Clear();
			string[] categoryNames = CategoryNames;
			foreach (string name in categoryNames)
			{
				int num = ((name == "Все") ? lastReport.TotalDetected : ((!(name == "Критические")) ? lastReport.Results.Count((CheckResult r) => r.Category == name && r.Detected) : lastReport.Results.Count((CheckResult r) => r.Detected && r.Severity == CheckSeverity.Critical)));
				ListViewItem listViewItem = new ListViewItem(name);
				listViewItem.SubItems.Add(num.ToString());
				listViewItem.Tag = name;
				if (num > 0)
				{
					listViewItem.ForeColor = ((name == "Критические" || name == "Все") ? Ui.AccentRed : ((name == "Визуалы (Следует проверить)") ? Ui.AccentPurple : Ui.AccentOrange));
				}
				else
				{
					listViewItem.ForeColor = Ui.TextSecondary;
				}
				categoryListView.Items.Add(listViewItem);
			}
			categoryListView.EndUpdate();
			int num2 = Array.IndexOf(CategoryNames, value);
			if (num2 < 0)
			{
				num2 = 0;
			}
			categoryListView.Items[num2].Selected = true;
			categoryListView.Items[num2].EnsureVisible();
		}

		private void RefreshResultsView()
		{
			if (lastReport == null)
			{
				resultsListView.Items.Clear();
				if (filterCounterLabel != null)
				{
					filterCounterLabel.Text = "";
				}
				return;
			}
			IEnumerable<CheckResult> source = lastReport.Results;
			if (currentCategory == "Критические")
			{
				source = source.Where((CheckResult r) => r.Detected && r.Severity == CheckSeverity.Critical);
			}
			else if (currentCategory != "Все")
			{
				source = source.Where((CheckResult r) => r.Category == currentCategory);
			}
			if (criticalOnlyCheck.Checked)
			{
				source = source.Where((CheckResult r) => r.Severity == CheckSeverity.Critical);
			}
			if (onlyDetectedCheck.Checked)
			{
				source = source.Where((CheckResult r) => r.Detected);
			}
			string q = searchBox.Text.Trim().ToLower();
			if (q.Length > 0)
			{
				source = source.Where((CheckResult r) => (r.Name != null && r.Name.ToLower().Contains(q)) || (r.Category != null && r.Category.ToLower().Contains(q)) || (r.Detail != null && r.Detail.ToLower().Contains(q)) || (r.Evidence != null && r.Evidence.ToLower().Contains(q)));
			}
			view = source.ToList();
			resultsListView.BeginUpdate();
			resultsListView.Items.Clear();
			foreach (CheckResult item in view)
			{
				resultsListView.Items.Add(BuildRow(item));
			}
			resultsListView.EndUpdate();
			if (filterCounterLabel != null)
			{
				filterCounterLabel.Text = "Показано " + view.Count + " из " + lastReport.Results.Count;
				filterCounterLabel.ForeColor = ((view.Count == 0) ? Ui.AccentOrange : Ui.TextMuted);
				filterCounterLabel.Location = new Point(((btnExportHtml != null) ? btnExportHtml.Right : resetFilterBtn.Right) + 12, 11);
			}
		}

		private ListViewItem BuildRow(CheckResult r)
		{
			string text = ((!r.Detected) ? "\ud83d\udfe2 ЧИСТО" : ((r.Severity == CheckSeverity.Critical) ? "\ud83d\udd34 БАН" : ((r.Severity == CheckSeverity.NeedsCheck) ? "\ud83d\udfe3 ПРОВЕРИТЬ" : ((r.Severity != CheckSeverity.Info) ? "\ud83d\udfe1 СЛЕД" : "\ud83d\udd35 ИНФО"))));
			ListViewItem listViewItem = new ListViewItem(text);
			listViewItem.SubItems.Add(r.Category);
			listViewItem.SubItems.Add(r.Name);
			string text2 = ExtractFirstPath(r.Evidence);
			if (string.IsNullOrEmpty(text2))
			{
				text2 = ExtractFirstPath(r.Detail);
			}
			listViewItem.SubItems.Add(string.IsNullOrEmpty(text2) ? "—" : text2);
			listViewItem.SubItems.Add(OneLine(r.Detail));
			listViewItem.Tag = r;
			listViewItem.ToolTipText = r.Name + "\n" + r.Detail;
			if (r.Detected)
			{
				if (r.Severity == CheckSeverity.Critical)
				{
					listViewItem.BackColor = Color.FromArgb(45, 18, 18);
					listViewItem.ForeColor = Color.FromArgb(255, 130, 130);
				}
				else if (r.Severity == CheckSeverity.NeedsCheck)
				{
					listViewItem.BackColor = Color.FromArgb(38, 20, 45);
					listViewItem.ForeColor = Color.FromArgb(220, 160, 255);
				}
				else if (r.Severity == CheckSeverity.Info)
				{
					listViewItem.BackColor = Color.FromArgb(18, 30, 40);
					listViewItem.ForeColor = Color.FromArgb(140, 205, 245);
				}
				else
				{
					listViewItem.BackColor = Color.FromArgb(40, 35, 15);
					listViewItem.ForeColor = Color.FromArgb(255, 220, 120);
				}
			}
			else
			{
				listViewItem.ForeColor = Color.FromArgb(120, 190, 130);
			}
			return listViewItem;
		}

		private static string OneLine(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return "";
			}
			return text.Replace("\r\n", " ").Replace('\n', ' ').Replace('\r', ' ');
		}

		private void ResultsListView_ColumnClick(object sender, ColumnClickEventArgs e)
		{
			if (e.Column < 0 || e.Column > 4)
			{
				return;
			}
			sortAscending = sortColumn != e.Column || !sortAscending;
			sortColumn = e.Column;
			Comparison<CheckResult> comparison = delegate(CheckResult a, CheckResult b)
			{
				int num = b.SeveritySortKey().CompareTo(a.SeveritySortKey());
				if (num != 0)
				{
					return num;
				}
				switch (e.Column)
				{
				case 1:
					return string.CompareOrdinal(a.Category, b.Category);
				case 2:
					return string.CompareOrdinal(a.Name, b.Name);
				case 3:
					return string.CompareOrdinal(ExtractFirstPath(a.Evidence), ExtractFirstPath(b.Evidence));
				case 4:
					return string.CompareOrdinal(a.Detail, b.Detail);
				default:
					return string.CompareOrdinal(a.Name, b.Name);
				}
			};
			view = view.OrderBy((CheckResult r) => r, Comparer<CheckResult>.Create(comparison)).ToList();
			if (!sortAscending)
			{
				view.Reverse();
			}
			resultsListView.BeginUpdate();
			resultsListView.Items.Clear();
			foreach (CheckResult item in view)
			{
				resultsListView.Items.Add(BuildRow(item));
			}
			resultsListView.EndUpdate();
		}

