			}
		}

		private void ResultsListView_DoubleClick(object sender, EventArgs e)
		{
			if (string.IsNullOrEmpty(currentDetectedPath) && resultsListView.SelectedItems.Count > 0)
			{
				CheckResult checkResult = resultsListView.SelectedItems[0].Tag as CheckResult;
				if (checkResult != null)
				{
					string value = ExtractFirstPath(checkResult.Evidence);
					if (string.IsNullOrEmpty(value))
					{
						value = ExtractFirstPath(checkResult.Detail);
					}
					currentDetectedPath = value;
				}
			}
			OpenTargetFolder();
		}

		private string ExtractFirstPath(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return "";
			}
			Match match = Regex.Match(text, "[a-zA-Z]:\\\\[^:\\*\\?\"<>\\|\\r\\n\\t]+");
			if (match.Success)
			{
				return match.Value.Trim().TrimEnd('.', ')', ' ', '\'');
			}
			return "";
		}

		private void UpdateTimerDisplay()
		{
			if (bedrockTimerLabel != null)
			{
				int num = Math.Max(0, ssMaxSeconds - ssElapsedSeconds);
				int num2 = num / 60;
				int num3 = num % 60;
				bedrockTimerLabel.Text = string.Format("⏱ Время SS: {0:D2}:{1:D2} ({2}с)", num2, num3, num);
				if (num <= 0)
				{
					ssTimer.Stop();
					bedrockTimerLabel.Text = "⏱ Время SS: ИСТЕКЛО — отказ от проверки";
					bedrockTimerLabel.ForeColor = Ui.AccentRed;
				}
				else if (isSsPaused)
				{
					bedrockTimerLabel.ForeColor = Ui.AccentOrange;
				}
				else if (num <= 60)
				{
					bedrockTimerLabel.ForeColor = Ui.AccentRed;
				}
				else if (num <= 120)
				{
					bedrockTimerLabel.ForeColor = Ui.AccentOrange;
				}
				else
				{
					bedrockTimerLabel.ForeColor = Color.FromArgb(255, 213, 79);
				}
			}
		}

		private void SsTimer_Tick(object sender, EventArgs e)
		{
			if (isSsPaused)
			{
				return;
			}
			ssElapsedSeconds++;
			UpdateTimerDisplay();
			if (ssMaxSeconds - ssElapsedSeconds > 0)
			{
				return;
			}
			ssTimer.Stop();
			try
			{
				SystemSounds.Exclamation.Play();
			}
			catch
			{
			}
		}

