		private void CheckContactText(string text)
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				CheckAnyDeskPresence();
				return;
			}
			Match match = Regex.Match(text, "\\b\\d{3}[ -]?\\d{3}[ -]?\\d{3}\\b");
			if (match.Success)
			{
				contactsStatusLabel.Text = "✅ AnyDesk: " + match.Value;
				contactsStatusLabel.ForeColor = Color.FromArgb(129, 199, 132);
				return;
			}
			Match match2 = Regex.Match(text, "(?i)(дискорд|дс|discord|ds)?[: ]*([a-zA-Z0-9_.-]{2,32}(#[0-9]{4})?)");
			if (match2.Success && match2.Groups[2].Length >= 3)
			{
				contactsStatusLabel.Text = "✅ Discord: " + match2.Groups[2].Value;
				contactsStatusLabel.ForeColor = Color.FromArgb(129, 199, 132);
			}
			else
			{
				contactsStatusLabel.Text = "Контакты введены";
