		private static string MakeSafeFileName(string raw)
		{
			if (string.IsNullOrEmpty(raw))
			{
				return "player";
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in raw)
			{
				stringBuilder.Append((char.IsLetterOrDigit(c) || c == '-' || c == '_' || c == '.') ? c : '_');
			}
			string text = stringBuilder.ToString().Trim('_');
			if (text.Length != 0)
			{
				if (text.Length <= 48)
				{
					return text;
				}
				return text.Substring(0, 48);
			}
			return "player";
		}

