		private void TrySetClipboardText(string text)
		{
			for (int i = 0; i < 4; i++)
			{
				try
				{
					Clipboard.SetText(text ?? "");
					return;
				}
				catch
				{
					Thread.Sleep(60);
				}
			}
			SetStatus("Буфер обмена занят — скопируйте команду вручную из строки состояния", Ui.AccentOrange);
		}

