		private void OpenFileInNotepad()
		{
			if (string.IsNullOrEmpty(currentDetectedPath))
			{
				return;
			}
			try
			{
				if (File.Exists(currentDetectedPath))
				{
					PlatformHelper.OpenFileInEditor(currentDetectedPath);
				}
				else
				{
					MessageBox.Show("Файл не существует или является папкой:\r\n" + currentDetectedPath, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Не удалось открыть файл: " + ex.Message, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

		private void OpenTargetFolder()
		{
			if (string.IsNullOrEmpty(currentDetectedPath))
			{
				SetStatus("В выбранной проверке нет файлового пути", Ui.AccentOrange);
				return;
			}
			try
			{
				if (File.Exists(currentDetectedPath))
				{
					PlatformHelper.SelectFileInFileManager(currentDetectedPath);
					return;
				}
				if (Directory.Exists(currentDetectedPath))
				{
					OpenInExplorer(currentDetectedPath);
					return;
				}
				string directoryName = Path.GetDirectoryName(currentDetectedPath);
				if (!string.IsNullOrEmpty(directoryName) && Directory.Exists(directoryName))
				{
					OpenInExplorer(directoryName);
				}
				else
				{
					MessageBox.Show("Папка или файл уже перемещён/удалён:\r\n" + currentDetectedPath, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Не удалось открыть папку: " + ex.Message, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

		private void OpenInExplorer(string folder)
		{
			try
			{
				if (!string.IsNullOrEmpty(folder) && Directory.Exists(folder))
				{
					PlatformHelper.OpenFolder(folder);
				}
				else
				{
					MessageBox.Show("Папка не найдена:\r\n" + folder, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Не удалось открыть папку: " + ex.Message, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

