		private void KillSuspiciousProcesses_Click()
		{
			string[] array = new string[12]
			{
				"cheatengine", "processhacker", "x64dbg", "x32dbg", "dnspy", "speedautoclicker", "autoclicker", "mangoclicker", "opautoclicker", "wireshark",
				"fiddler", "fiddlerclassic"
			};
			int num = 0;
			List<string> list = new List<string>();
			string[] array2 = array;
			foreach (string processName in array2)
			{
				try
				{
					Process[] processesByName = Process.GetProcessesByName(processName);
					foreach (Process process in processesByName)
					{
						try
						{
							process.Kill();
							num++;
							list.Add(process.ProcessName + " (PID " + process.Id + ")");
						}
						catch
						{
						}
					}
				}
				catch
				{
				}
			}
			if (num > 0)
			{
				MessageBox.Show("Завершено процессов: " + num + "\r\n\r\n" + string.Join("\r\n", list.ToArray()), "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
			else
			{
				MessageBox.Show("Активных процессов кликеров, инжекторов или отладчиков не обнаружено.", "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
		}

		private void ScreenshotBtn_Click(object sender, EventArgs e)
		{
			try
			{
				Rectangle virtualScreen = SystemInformation.VirtualScreen;
				using (Bitmap bitmap = new Bitmap(virtualScreen.Width, virtualScreen.Height))
				{
					string text = PlayerOrFallback();
					using (Graphics graphics = Graphics.FromImage(bitmap))
					{
						graphics.CopyFromScreen(virtualScreen.Location, Point.Empty, virtualScreen.Size);
						int num = 40;
						using (SolidBrush brush = new SolidBrush(Color.FromArgb(220, 15, 18, 25)))
						{
							graphics.FillRectangle(brush, 0, virtualScreen.Height - num, virtualScreen.Width, num);
						}
						using (Font font = new Font("Segoe UI", 11.5f, FontStyle.Bold))
						{
							using (SolidBrush brush2 = new SolidBrush(Color.FromArgb(100, 255, 218)))
							{
								string s = "MC CHEAT CHECKER (Community Edition) | Игрок: " + text + " | Модератор: " + moderatorBox.Text.Trim() + " | " + DateTime.Now.ToString("dd.MM.yyyy HH:mm:ss");
								graphics.DrawString(s, font, brush2, new PointF(20f, virtualScreen.Height - num + 8));
							}
						}
					}
					try
					{
						Clipboard.SetImage(bitmap);
					}
					catch
					{
					}
					SetStatus("✅ Скриншот скопирован в буфер обмена (без сохранения на диск)", Ui.AccentGreen);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Ошибка создания скриншота: " + ex.Message, "MC Cheat Checker", MessageBoxButtons.OK, MessageBoxIcon.Hand);
			}
		}

		private void MainForm_KeyDown(object sender, KeyEventArgs e)
		{
			bool flag = base.ActiveControl is TextBox;
			if (e.KeyCode == Keys.F5)
			{
				if (startButton.Enabled)
				{
					StartButton_Click(this, EventArgs.Empty);
				}
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.KeyCode == Keys.Escape)
			{
				if (stopButton.Enabled)
				{
					StopButton_Click(this, EventArgs.Empty);
				}
				else if (searchBox != null && !string.IsNullOrEmpty(searchBox.Text))
				{
					searchBox.Clear();
				}
				e.Handled = true;
			}
			else if (e.Control && e.KeyCode == Keys.F)
			{
				searchBox.Focus();
				searchBox.SelectAll();
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.S)
			{
				SaveReportBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.H)
			{
				ExportHtmlBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.J)
			{
				ExportJsonBtn_Click();
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.D)
			{
				DiscordReportBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.Z)
			{
				ZipPackageBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.Control && e.KeyCode == Keys.P)
			{
				ScreenshotBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (e.KeyCode == Keys.F1)
			{
				bottomTabs.SelectedIndex = 2;
				MessageBox.Show(GetHowItWorksText(), "MC Cheat Checker — Инструкция модератора", MessageBoxButtons.OK, MessageBoxIcon.Information);
				e.SuppressKeyPress = true;
			}
			else if (e.KeyCode == Keys.F2)
			{
				bottomTabs.SelectedIndex = 2;
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
			else if (!flag && e.KeyCode == Keys.Space)
			{
				PauseTimerBtn_Click(this, EventArgs.Empty);
				e.Handled = true;
				e.SuppressKeyPress = true;
			}
		}

