		private static Color ParseRgb(string csv)
		{
			string[] array = csv.Split(',');
			if (array.Length != 3)
			{
				return Ui.SurfaceAlt;
			}
			return Color.FromArgb(int.Parse(array[0]), int.Parse(array[1]), int.Parse(array[2]));
		}

		private static Icon BuildAppIcon()
		{
			using (Bitmap bitmap = new Bitmap(32, 32))
			{
				using (Graphics graphics = Graphics.FromImage(bitmap))
				{
					graphics.SmoothingMode = SmoothingMode.AntiAlias;
					graphics.Clear(Color.Transparent);
					Point[] points = new Point[6]
					{
						new Point(16, 2),
						new Point(29, 7),
						new Point(29, 16),
						new Point(16, 30),
						new Point(3, 16),
						new Point(3, 7)
					};
					using (SolidBrush brush = new SolidBrush(Color.FromArgb(24, 27, 33)))
					{
						graphics.FillPolygon(brush, points);
					}
					using (Pen pen = new Pen(Ui.AccentTeal, 2f))
					{
						graphics.DrawPolygon(pen, points);
					}
					using (Pen pen2 = new Pen(Ui.AccentTeal, 3.2f))
					{
						pen2.StartCap = LineCap.Round;
						pen2.EndCap = LineCap.Round;
						graphics.DrawLines(pen2, new Point[3]
						{
							new Point(10, 16),
							new Point(15, 21),
							new Point(23, 11)
						});
					}
				}
				return Icon.FromHandle(bitmap.GetHicon());
			}
		}

